// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace Campground.Shared.I18n
{
    /// <summary>A problem found by <see cref="Strings.Validate"/>.</summary>
    internal sealed record StringProblem(string Language, string Key, string Problem);

    /// <summary>
    /// Flat JSON string tables embedded as resources named <c>&lt;prefix&gt;.&lt;lang&gt;.json</c>
    /// (e.g. <c>GameTent.i18n.en.json</c>, <c>GameTent.i18n.pt-BR.json</c>). Lookup falls back
    /// pt-BR → pt → en → the key itself. Placeholders are <c>{name}</c>.
    /// </summary>
    internal sealed class Strings
    {
        internal const string Fallback = "en";

        private static readonly Regex Placeholder = new(@"\{([A-Za-z0-9_]+)\}", RegexOptions.Compiled);

        private readonly Dictionary<string, IReadOnlyDictionary<string, string>> _tables;

        private readonly List<StringProblem> _parseProblems;
        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, IReadOnlyDictionary<string, string>> _merged = new(StringComparer.OrdinalIgnoreCase);

        private Strings(Dictionary<string, IReadOnlyDictionary<string, string>> tables, List<StringProblem> parseProblems)
        {
            _tables = tables;
            _parseProblems = parseProblems;
        }

        /// <summary>Languages present.</summary>
        internal IReadOnlyCollection<string> Languages => _tables.Keys;

        /// <summary>Loads every table under the prefix from the assembly.</summary>
        internal static Strings Load(Assembly assembly, string prefix)
        {
            var tables = new Dictionary<string, IReadOnlyDictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
            var problems = new List<StringProblem>();
            foreach (var name in assembly.GetManifestResourceNames())
            {
                if (!name.StartsWith(prefix + ".", StringComparison.Ordinal) || !name.EndsWith(".json", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var lang = name.Substring(prefix.Length + 1, name.Length - prefix.Length - 6);
                using var stream = assembly.GetManifestResourceStream(name)!;
                using var reader = new StreamReader(stream);
                tables[lang] = Parse(lang, reader.ReadToEnd(), problems);
            }

            return new Strings(tables, problems);
        }

        /// <summary>Builds from in-memory JSON tables (tests, tools).</summary>
        internal static Strings FromJson(IReadOnlyDictionary<string, string> jsonByLanguage)
        {
            var problems = new List<StringProblem>();
            var tables = jsonByLanguage.ToDictionary(p => p.Key, p => Parse(p.Key, p.Value, problems), StringComparer.OrdinalIgnoreCase);
            return new Strings(tables, problems);
        }

        /// <summary>The table for a language with fallbacks merged in (for sending to the browser). Built once per language.</summary>
        internal IReadOnlyDictionary<string, string> TableFor(string? language)
            => _merged.GetOrAdd(language ?? string.Empty, _ => BuildTable(language));

        private IReadOnlyDictionary<string, string> BuildTable(string? language)
        {
            var merged = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var lang in Chain(language).Reverse())
            {
                if (_tables.TryGetValue(lang, out var t))
                {
                    foreach (var (k, v) in t)
                    {
                        merged[k] = v;
                    }
                }
            }

            return merged;
        }

        /// <summary>Looks up and formats a string.</summary>
        internal string Get(string key, string? language = null, IReadOnlyDictionary<string, object?>? args = null)
        {
            foreach (var lang in Chain(language))
            {
                if (_tables.TryGetValue(lang, out var t) && t.TryGetValue(key, out var value))
                {
                    return args == null ? value : Format(value, args);
                }
            }

            return key;
        }

        /// <summary>Replaces {name} placeholders; unknown ones are left as is.</summary>
        internal static string Format(string template, IReadOnlyDictionary<string, object?> args)
            => Placeholder.Replace(template, m => args.TryGetValue(m.Groups[1].Value, out var v)
                ? Convert.ToString(v, CultureInfo.InvariantCulture) ?? string.Empty
                : m.Value);

        /// <summary>
        /// Checks every table against English: missing keys, extra keys, placeholder mismatches, empty values.
        /// Plugin CI runs this so a translation never ships broken.
        /// </summary>
        internal IReadOnlyList<StringProblem> Validate()
        {
            var problems = new List<StringProblem>(_parseProblems);
            if (!_tables.TryGetValue(Fallback, out var en))
            {
                problems.Add(new StringProblem(Fallback, "*", "There is no English table."));
                return problems;
            }

            foreach (var (lang, table) in _tables)
            {
                foreach (var (key, value) in table)
                {
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        problems.Add(new StringProblem(lang, key, "empty value"));
                    }

                    if (!string.Equals(lang, Fallback, StringComparison.OrdinalIgnoreCase))
                    {
                        if (!en.TryGetValue(key, out var source))
                        {
                            problems.Add(new StringProblem(lang, key, "key is not in English"));
                        }
                        else if (!Names(source).SetEquals(Names(value)))
                        {
                            problems.Add(new StringProblem(lang, key, $"placeholders differ from English ({string.Join(",", Names(source))})"));
                        }
                    }
                }

                if (!string.Equals(lang, Fallback, StringComparison.OrdinalIgnoreCase))
                {
                    foreach (var missing in en.Keys.Where(k => !table.ContainsKey(k)))
                    {
                        problems.Add(new StringProblem(lang, missing, "missing (English will show)"));
                    }
                }
            }

            return problems;
        }

        private static IEnumerable<string> Chain(string? language)
        {
            if (!string.IsNullOrWhiteSpace(language))
            {
                yield return language;
                var dash = language.IndexOf('-');
                if (dash > 0)
                {
                    yield return language.Substring(0, dash);
                }
            }

            yield return Fallback;
        }

        private static HashSet<string> Names(string s)
            => Placeholder.Matches(s).Select(m => m.Groups[1].Value).ToHashSet(StringComparer.Ordinal);

        // A value that isn't a string is left out of the table and a repeated key keeps the last value; both are
        // reported by Validate so a bad translation file doesn't just lose text.
        private static IReadOnlyDictionary<string, string> Parse(string language, string json, List<StringProblem> problems)
        {
            var result = new Dictionary<string, string>(StringComparer.Ordinal);
            using var doc = JsonDocument.Parse(json, new JsonDocumentOptions { CommentHandling = JsonCommentHandling.Skip, AllowTrailingCommas = true });
            foreach (var p in doc.RootElement.EnumerateObject())
            {
                if (p.Value.ValueKind != JsonValueKind.String)
                {
                    problems.Add(new StringProblem(language, p.Name, "value is not a string"));
                }
                else
                {
                    if (result.ContainsKey(p.Name))
                    {
                        problems.Add(new StringProblem(language, p.Name, "duplicate key"));
                    }

                    result[p.Name] = p.Value.GetString()!;
                }
            }

            return result;
        }
    }
}
